wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract's `requires len(text) <= 100000` holds of every input,
        // so the text is forwarded as-is to the one channel this node holds.
        let confirmation = response_channel::send(&reply.text);

        // The session identity belongs to the host channel; this node must not
        // fabricate it, nor claim a delivery the channel did not confirm.
        // If the postconditions cannot be met honestly, trap rather than emit
        // an output that violates `ensures delivered == true` /
        // `ensures present(session_id)`.
        if !confirmation.delivered {
            panic!("response channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: true,
        }
    }
}

export!(Node);
